import React from 'react';
import BurgerLogo from '/../assets/burgerlogo.png';

export const Navbar = () => {
    return (
        <div className='navbar'>
            <div className='main'>
                <img src={BurgerLogo} alt="Burger Logo" />
            </div>
        </div> // Closing the outer div
    );
};
